+	cpu_set_t old_mask, mask;
+	int pagemap_fd, kpageflags_fd;
+	unsigned long pfn;
+	uint64_t flags;
+	int cpu, fd, retry;
+	bool active = false;
+
+	if (geteuid()) {
+		munmap(drain, page_size);
+		ksft_test_result_skip("requires root to read page flags\n");
+		return;
+	}
